SELECT 'TABLES' AS section, TABLE_NAME, TABLE_ROWS, '' AS c3, '' AS c4 FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() ORDER BY TABLE_NAME;
SELECT 'COLUMNS' AS section, TABLE_NAME, COLUMN_NAME, DATA_TYPE, COLUMN_KEY FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND (LOWER(TABLE_NAME) LIKE '%pasien%' OR LOWER(TABLE_NAME) LIKE '%patient%' OR LOWER(TABLE_NAME) LIKE '%rekam%' OR LOWER(TABLE_NAME) LIKE '%registr%' OR LOWER(TABLE_NAME) LIKE '%daftar%' OR LOWER(TABLE_NAME) LIKE '%kunjung%' OR LOWER(TABLE_NAME) LIKE '%rawat%' OR LOWER(TABLE_NAME) LIKE '%diagn%' OR LOWER(TABLE_NAME) LIKE '%icd%' OR LOWER(TABLE_NAME) LIKE '%resep%' OR LOWER(TABLE_NAME) LIKE '%obat%' OR LOWER(TABLE_NAME) LIKE '%farm%' OR LOWER(TABLE_NAME) LIKE '%lab%' OR LOWER(TABLE_NAME) LIKE '%radio%' OR LOWER(TABLE_NAME) LIKE '%rad%' OR LOWER(TABLE_NAME) LIKE '%tindak%' OR LOWER(TABLE_NAME) LIKE '%billing%' OR LOWER(TABLE_NAME) LIKE '%bayar%' OR LOWER(TABLE_NAME) LIKE '%sep%' OR LOWER(TABLE_NAME) LIKE '%bpjs%' OR LOWER(TABLE_NAME) LIKE '%antri%' OR LOWER(TABLE_NAME) LIKE '%poli%' OR LOWER(TABLE_NAME) LIKE '%dokter%' OR LOWER(COLUMN_NAME) LIKE '%pasien%' OR LOWER(COLUMN_NAME) LIKE '%patient%' OR LOWER(COLUMN_NAME) LIKE '%no_rm%' OR LOWER(COLUMN_NAME) LIKE '%norm%' OR LOWER(COLUMN_NAME) LIKE '%nomr%' OR LOWER(COLUMN_NAME) LIKE '%rekam%' OR LOWER(COLUMN_NAME) LIKE '%registr%' OR LOWER(COLUMN_NAME) LIKE '%daftar%' OR LOWER(COLUMN_NAME) LIKE '%kunjung%' OR LOWER(COLUMN_NAME) LIKE '%rawat%' OR LOWER(COLUMN_NAME) LIKE '%diagn%' OR LOWER(COLUMN_NAME) LIKE '%icd%' OR LOWER(COLUMN_NAME) LIKE '%resep%' OR LOWER(COLUMN_NAME) LIKE '%obat%' OR LOWER(COLUMN_NAME) LIKE '%lab%' OR LOWER(COLUMN_NAME) LIKE '%radio%' OR LOWER(COLUMN_NAME) LIKE '%rad%' OR LOWER(COLUMN_NAME) LIKE '%tindak%' OR LOWER(COLUMN_NAME) LIKE '%billing%' OR LOWER(COLUMN_NAME) LIKE '%sep%' OR LOWER(COLUMN_NAME) LIKE '%bpjs%' OR LOWER(COLUMN_NAME) LIKE '%poli%' OR LOWER(COLUMN_NAME) LIKE '%dokter%') ORDER BY TABLE_NAME, ORDINAL_POSITION;
SELECT 'FK' AS section, TABLE_NAME, COLUMN_NAME, REFERENCED_TABLE_NAME, REFERENCED_COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA = DATABASE() AND REFERENCED_TABLE_NAME IS NOT NULL ORDER BY TABLE_NAME, COLUMN_NAME;